    def build(self, x: np.ndarray) -> dict:
        x = np.where(x > 0.0, x, 0.0)
        if self.mode == 'route':
            # A route commodity with a single available slot is forced: state
            # its exact demand instead of the round-off of the linear solve.
            for gi in range(self.G):
                vs = self.group_vars[gi]
                if len(vs) == 1:
                    x[vs[0]] = float(self.mass[gi])
        flows: List[List[float]] = []
        for gi in range(self.G):
            row = [0.0] * self.slot_counts[gi]
            for j in self.group_vars[gi]:
                row[self.var_slot[j]] = float(x[j])
            flows.append(row)
        G = self.gradient(x)
        potentials: List[float] = []
        for gi in range(self.G):
            vs = self.group_vars[gi]
            lam = 0.0
            if vs and any(x[j] != 0.0 for j in vs):
                lam = -float(min(G[j] for j in vs))
                if lam < 0.0:
                    # Admit potentials are multipliers of an upper bound: the
                    # exact value is never negative, tiny negatives are pure
                    # round-off of a slack constraint.
                    lam = 0.0 if self.mode == 'admit' else lam
            if -1e-12 < lam < 1e-12:
                # Snapping a round-off sized multiplier can only move the
                # certificate by demand * 1e-12, far inside the tolerance.
                lam = 0.0
            potentials.append(lam if lam != 0.0 else 0.0)
        load = self.loads(x)
        load[~self.live] = 0.0
        flows = [[(v if v != 0.0 else 0.0) for v in row] for row in flows]
        load = [float(v) for v in load]
        load = [(v if v != 0.0 else 0.0) for v in load]
        return {'status': 'optimal', 'flow': flows,
                'edge_load': load, 'potential': potentials,
                '_x': x, '_G': G}

    def check(self, report: dict):
        """Feasibility + tangent lower bound, exactly as the protocol states it."""
        x = report['_x']
        G = report['_G']
        f = self.objective(x)
        term = lam_sum = 0.0
        worst = 0.0
        slack = None
        for gi in range(self.G):
            vs = self.group_vars[gi]
            if not vs:
                continue
            idx = np.asarray(vs)
            lam = report['potential'][gi]
            sub = float(np.min(G[idx] + lam))
            worst = min(worst, sub)
            term += float(np.dot(x[idx], G[idx]))
            lam_sum += lam * float(self.mass[gi])
            total = float(np.sum(x[idx]))
            if self.mode == 'route':
                bad = abs(total - self.mass[gi]) - tol(total, self.mass[gi])
            else:
                bad = total - self.mass[gi] - tol(total, self.mass[gi])
            slack = bad if slack is None else max(slack, bad)
        D = f - term - lam_sum
        gap = abs(f - D)
        allowed = max(ACCEPT_ABS, ACCEPT_REL * abs(f))
        feasible = (slack is None or slack <= 0.0)
        if self.mode == 'admit' and report['potential'] and min(report['potential']) < 0.0:
            feasible = False
        for gi in range(self.G):
            if self.mass[gi] <= 0 and report['potential'][gi] != 0.0:
                feasible = False
        ok = feasible and gap <= allowed and worst >= -ACCEPT_ABS
        score = min((allowed - gap) / allowed, (CHECK_ABS + worst) / CHECK_ABS)
        return ok, score


